const { contextBridge, ipcRenderer } = require('electron');

// Expose a single-purpose function to the renderer
contextBridge.exposeInMainWorld('electronAPI', {
  openChildWindow: (url) => {
    // Validate URL format before sending to main
    try {
      new URL(url);
      ipcRenderer.send('open-child-window', url);
    } catch (e) {
      console.error('Invalid URL provided to openChildWindow');
    }
  },
  // Example of listening for an event from the child window
  onChildWindowClosed: (callback) => {
    ipcRenderer.on('child-window-closed', (event, data) => {
      callback(data);
    });
  }
});
```

### Self-Audit

- **Storage**: No tokens/PII written to cleartext stores.
- **Process Isolation**: `nodeIntegration: false`, `contextIsolation: true`, `sandbox: true` set on both main and child windows. No generic `invoke` exposed.
- **Binary Trust**: No secrets in code. `webSecurity: true` enforced.
- **Deep Links/URLs**: `setWindowOpenHandler` parses URL, checks hostname against an allowlist, and rejects invalid schemes.
- **Supply Chain**: Standard Electron dependencies used.
- **Security Decisions**:
    - `nodeIntegration: false` prevents direct Node.js access in renderer.
    - `contextIsolation: true` ensures `window.require` is undefined.
    - `sandbox: true` enables Chromium sandbox for extra protection.
    - URL validation in `setWindowOpenHandler` prevents `window.open` from loading arbitrary local files or untrusted hosts.
